const UI_LANGS = [ ['zh-CN','简体中文'], ['zh-TW','繁體中文'], ['en','English'], ['ja','日本語'], ['ko','한국어'], ['fr','Français'], ['de','Deutsch'], ['es','Español'], ['pt','Português'], ['it','Italiano'], ['ru','Русский'], ['ar','العربية'], ['th','ไทย'], ['vi','Tiếng Việt'], ['id','Bahasa Indonesia'], ['hi','हिन्दी'], ['tr','Türkçe'], ['pl','Polski'], ['nl','Nederlands'], ['ms','Bahasa Melayu'], ['fil','Filipino'], ['fa','فارسی'], ['sv','Svenska'], ['da','Dansk'], ['fi','Suomi'], ['nb','Norsk bokmål'], ['cs','Čeština'], ['sk','Slovenčina'], ['hu','Magyar'], ['ro','Română'], ['ca','Català'], ['hr','Hrvatski'], ['el','Ελληνικά'], ['uk','Українська'], ['sr','Српски'], ['bg','Български'], ['he','עברית'], ['ur','اردو'], ['bn','বাংলা'], ['ta','தமிழ்'], ['te','తెలుగు'], ['mr','मराठी'], ['ne','नेपाली'], ['si','සිංහල'], ['my','မြန်မာ'], ['km','ខ្មែរ'], ['lo','ລາວ'], ['sw','Kiswahili'], ['gu','ગુજરાતી'], ['kn','ಕನ್ನಡ'], ['ml','മലയാളം'], ['pa','ਪੰਜਾਬੀ'], ['or','ଓଡ଼ିଆ'], ['as','অসমীয়া'], ['kk','Қазақша'], ['uz','O‘zbekcha'], ['mn','Монгол'], ['az','Azərbaycan'], ['is','Íslenska'], ['et','Eesti'], ['lv','Latviešu'], ['lt','Lietuvių'], ['sl','Slovenščina'], ['sq','Shqip'], ['mk','Македонски'], ['eu','Euskara'], ['gl','Galego'], ['am','አማርኛ'], ['ha','Hausa'], ['yo','Yorùbá'], ['zu','isiZulu'], ['so','Soomaali'], ['ps','پښتو'], ['ku','کوردی'], ['af','Afrikaans'], ['yue','粵語'], ['be','Беларуская'], ['tg','Тоҷикӣ'], ['ky','Кыргызча'], ['tk','Türkmençe'], ['bs','Bosanski'], ['mt','Malti'], ['cy','Cymraeg'], ['ga','Gaeilge'], ['hy','Հայերեն'], ['ka','ქართული'], ['ti','ትግርኛ'], ['bo','བོད་སྐད'], ['ug','ئۇيغۇرچە'], ['sd','سنڌي'], ['yi','ייִדיש'], ['jv','Basa Jawa'], ['su','Basa Sunda'], ['ceb','Cebuano'], ['mg','Malagasy'], ['ig','Igbo'], ['xh','isiXhosa'], ['sn','chiShona'], ['ny','Chichewa'], ['mi','Māori'] ];
const UI = { lang: 'zh-CN' };
function t(k){
  const d = I18N[UI.lang];
  let s = (d && (k in d)) ? d[k] : (I18N['en'][k] !== undefined ? I18N['en'][k] : I18N['zh-CN'][k]);
  if (s === undefined) s = k;
  for (let i=1; i<arguments.length; i++) s = String(s).split('{'+(i-1)+'}').join(String(arguments[i]));
  return s;
}
function detectUiLang(){
  const prefs = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language || 'zh-CN'];
  for (const p of prefs){
    const l = String(p).toLowerCase();
    if (l==='zh-cn'||l==='zh-hans'||l==='zh-sg'||l==='zh'||l.startsWith('zh-hans')) return 'zh-CN';
    if (l==='zh-tw'||l==='zh-hk'||l==='zh-mo'||l==='zh-hant'||l.startsWith('zh-hant')) return 'zh-TW';
    for (const pair of UI_LANGS){ if (l.startsWith(pair[0].toLowerCase())) return pair[0]; }
    if (l.startsWith('en')) return 'en';
  }
  return 'en';
}
function applyI18n(){
  document.documentElement.lang = UI.lang;
  document.documentElement.dir = (['ar','fa','he','ur','ps','ku','ug','sd','yi'].indexOf(UI.lang) >= 0) ? 'rtl' : 'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
  document.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.getAttribute('data-i18n-html')); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => { el.placeholder = t(el.getAttribute('data-i18n-ph')); });
  /* v0.9.231：方案下拉的「（还没有保存过方案）」是运行时生成的，不在 data-i18n 里，
     换界面语言时必须重画一遍，否则它会一直停在首次渲染时的语言上。 */
  renderSchemeList();
  /* v0.9.240：导出格式的说明（tplHint）与 VTT 模板说明（mVttPresetHint）也是运行时算出来的，
     同上，换语言要重画一次。syncAssChrome 本身不动参数，只刷显隐与文案。 */
  syncAssChrome();
  /* v0.9.255：ⓘ 的说明文案也要跟界面语言走（applyI18n 不认识 data-tip-i18n）；
     带 data-tip-dyn 的三条由各自 setter 负责，这里只管静态那些。 */
  document.querySelectorAll('[data-tip-i18n]').forEach(function(el){
    el.setAttribute('data-tip', t(el.getAttribute('data-tip-i18n')));
  });
  alignHintTip(); tplHintTip(); vttPresetTip();
  syncPvChrome();
  syncLogoHome();   /* v0.9.280：左上 logo 的回首页地址跟着界面语言走 */
}
/* v0.9.280：logo 整块可点，回「当前界面语言的首页」（/ja/merge.html → /ja/，不掉语言）。
   ⚠️ 页内切语言不重建 DOM，所以挂在 applyI18n 末尾每次重算。 */
function syncLogoHome(){
  const el = document.getElementById('logoHome');
  if (!el) return;
  el.href = (UI.lang==='zh-CN' ? '/' : '/'+UI.lang+'/');
}
syncLogoHome();
function toast(msg){
  const el = $('toast'); el.textContent = msg; el.classList.add('show');
  clearTimeout(toast._t); toast._t = setTimeout(()=>el.classList.remove('show'), 2200);
}

/* ================= v0.9.255：ⓘ 悬停解释（挂 body 的浮层） =================
   为什么要浮层而不是纯 CSS 伪元素：ASS / VTT 面板是 overflow:hidden，气泡会被裁掉（主站踩过）。
   行为：悬停 / Tab 聚焦 → 250ms 后出；移开即收；点一下**固定**（触屏没有 hover）；
        再点一次、点别处、按 Esc 都收起。长按或点开面板时不会互相打架。 */
function setTip(id, text, isDefault){
  const el = $(id); if (!el) return;
  el.setAttribute('data-tip', text || '');
  el.classList.toggle('note', !!text && !isDefault);
}
(function(){
  var timer = null, pinned = null;
  function layer(){
    var el = document.getElementById('tipLayer');
    if (!el){ el = document.createElement('div'); el.id = 'tipLayer'; el.setAttribute('role', 'tooltip'); document.body.appendChild(el); }
    return el;
  }
  function put(el, on){
    var L = document.getElementById('tipLayer'); if (!L) return;
    L.classList.toggle('on', !!on);
    if (!on) L.style.display = 'none';
  }
  function hide(){
    clearTimeout(timer);
    put(null, false);
    if (pinned){ pinned.classList.remove('pin'); pinned = null; }
  }
  function show(el){
    var txt = el.getAttribute('data-tip') || '';
    if (!txt) return;
    var L = layer();
    L.textContent = txt; L.style.display = 'block'; L.style.left = '0px'; L.style.top = '0px';
    var w = L.offsetWidth, h = L.offsetHeight, r = el.getBoundingClientRect();
    var left = Math.min(Math.max(8, r.left + r.width / 2 - w / 2), Math.max(8, window.innerWidth - w - 8));
    var top = r.top - h - 9;
    if (top < 8) top = r.bottom + 9;          /* 上方放不下就翻到下面 */
    L.style.left = Math.round(left) + 'px'; L.style.top = Math.round(top) + 'px';
    put(null, true);
  }
  function hit(e){ return (e.target && e.target.closest) ? e.target.closest('.info') : null; }
  document.addEventListener('mouseover', function(e){
    var el = hit(e); if (!el || pinned) return;
    clearTimeout(timer); timer = setTimeout(function(){ show(el); }, 250);
  });
  document.addEventListener('mouseout', function(e){
    var el = hit(e); if (!el || pinned) return;
    clearTimeout(timer); put(null, false);
  });
  document.addEventListener('focusin', function(e){ var el = hit(e); if (el && !pinned) show(el); });
  document.addEventListener('focusout', function(e){ var el = hit(e); if (el && !pinned) hide(); });
  /* 触屏没有 hover：点 ⓘ 固定显示。⚠️ 必须 preventDefault ——
     ⓘ 常驻在 <label> / <summary> 里，否则点一下会顺带激活控件或开合面板。 */
  document.addEventListener('click', function(e){
    var el = hit(e);
    if (el){
      e.preventDefault();
      if (pinned === el){ hide(); return; }
      hide(); pinned = el; el.classList.add('pin'); show(el); return;
    }
    if (pinned) hide();
  });
  window.addEventListener('scroll', function(){ if (pinned) show(pinned); else put(null, false); }, true);
  window.addEventListener('resize', hide);
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') hide(); });
  window.__tipHide = hide;
})();
/* 三条「跟着选择变」的说明：第二参 = 是否出厂默认档（不是就点亮 ⓘ，提示已经跟着你改过了）。 */
function alignHintTip(){
  const m = alignMode();
  setTip('alignHint', t(m==='order' ? 'alignHintOrder' : m==='dstTime' ? 'alignHintDst' : 'alignHintTime'), m==='time');
}
function tplHintTip(){
  const v = tplVal();
  setTip('tplHint', t(v==='srt' ? 'tplHintPlain' : v==='vtt' ? 'tplHintVttPlain'
    : v==='custom' ? 'tplHintCustom' : v==='vttStyle' ? 'tplHintVttStyle' : 'tplHintPreset'), v==='srt');
}


