    css.fontStyle = o.italic ? 'italic' : 'normal';
    css.letterSpacing = (o.spacing * k).toFixed(2) + 'px';
    css.textAlign = o.align === 1 ? 'left' : (o.align === 3 ? 'right' : 'center');
    css.paddingLeft = MLP; css.paddingRight = MRP;
    css.top = 'auto';
